// Build the Claude prompt for this lead.
// We embed the critical skill rules directly since n8n can't load .md files.
const lead = $json;

let notes = {};
try { notes = JSON.parse(lead.notes || '{}'); } catch {}

const personalization_line = notes.personalization_line || '';
const website = notes.website || lead.website_notes || '';

const systemPrompt = `You are writing a cold email for Isaac at Twenty1 Media.

IMPORTANT RULES (non-negotiable):
- ZERO em dashes anywhere in the body. Only on signoff line. Use commas/periods instead.
- NEVER guarantee marketing outcomes (bookings, leads, traffic, revenue). Isaac sells a TOOL (website + booking engine), NOT marketing.
- NEVER fabricate personal history. Isaac is a bass fisherman in Indiana. NOT walleye, NOT Minnesota.
- NEVER include links, prices, or corporate signatures.
- Use "I" not "we". Sign off as "— Isaac".
- Under 150 words. 4 paragraphs max.
- One specific CTA with a proposed day/time.
- No words: leverage, streamline, empower, unlock, elevate, seamless, robust, cutting-edge, delve, landscape, realm.
- Write like a text message to a friend who runs a lodge.

4-STEP FRAMEWORK:
1. Personalization (1-2 sentences): cold reading or specific observation + voluntary disclosure about Isaac (bass fisherman in Indiana)
2. Who am I (1-2 sentences): "I'm Isaac, I run Twenty1 Media" + one named client (Waterway Inn, Papin's Resort, IVR906)
3. Offer (1-2 sentences): "I'll build you [specific deliverable] in [14 days]. You don't pay until it's live in your hands."
4. CTA (1 sentence): specific day/time for a quick call

ISAAC'S VOICE:
- Openers: "Hey [name]," — simple
- Words he uses: "you guys", "let's face it", "taken care of", "get you rolling", "quick call"
- Comfortable with fragments, run-ons, contractions always
- PS with real scarcity is fine ("only taking 3 lodges this month")
- Match tone of texting a buddy`;

const userPrompt = `Write a cold email to:
Name: ${lead.contact_name || 'the owner'}
Business: ${lead.business_name}
Location: ${[lead.city, lead.state].filter(Boolean).join(', ') || 'unknown'}
Website: ${website}
Existing personalization note: ${personalization_line}

Output ONLY the email in this format:
Subject: <lowercase, under 50 chars, plausible deniability>

<email body>

— Isaac`;

return {
  json: {
    ...lead,
    system_prompt: systemPrompt,
    user_prompt: userPrompt,
    website,
    personalization_line
  }
};

// Extract subject + body from Claude's response and validate
const lead = $('Build Claude Prompt').item.json;
const raw = $json.content?.[0]?.text || '';
const config = $('Config').item.json;

// Parse subject and body
const subjectMatch = raw.match(/^Subject:\s*(.+)/im);
const subject = subjectMatch ? subjectMatch[1].trim() : 'quick question';

// Body = everything after "Subject: ..." line, trimmed
let body = raw.replace(/^Subject:\s*.+\n*/im, '').trim();

// Validation checks
const issues = [];
if (body.includes('—') && !body.match(/^— Isaac$/m)) {
  // Has em dash NOT on signoff line
  const cleaned = body.replace(/—(?!\s*Isaac\s*$)/gm, ',');
  body = cleaned;
  issues.push('removed em dashes');
}
if (body.split(/\s+/).length > 160) issues.push('over 150 words');
if (/https?:\/\//i.test(body)) issues.push('contains link');
if (/\$\d/.test(body)) issues.push('contains price');

return {
  json: {
    prospect_id: lead.id,
    business_name: lead.business_name,
    email: lead.email,
    contact_name: lead.contact_name,
    subject,
    body,
    validation_issues: issues,
    dry_run: config.dry_run,
    sent_by: 'isaac'
  }
};

